function BambooQuestComponent:Initial(jsonData)
    jsonData = checkTable(jsonData)

    self._allActivity = {}
    --[[
    for k, v in pairs(jsonData) do
        local dojo = BambooActivityDojo.New()
        dojo:Fill(v)
        self._allActivity[checkString(v.activityUuid)] = dojo

        self._curActivityId = checkNumber(dojo.activityId)  
        self._curactivityUuid = checkNumber(dojo.activityUuid)  
    end
    ]]
    local dojo = BambooActivityDojo.New()
    dojo.activityUuid = checkNumber(jsonData.id)    --uuid
    dojo.activityId = checkNumber(jsonData.type)      --活动id
    dojo.startTime = checkNumber(jsonData.startTime)       --开始倒计时
    dojo.endTime = checkNumber(jsonData.endTime)         --结束倒计时
    dojo.closeTime = checkNumber(jsonData.closeTime)       --关闭倒计时
    self._allActivity[checkString(dojo.activityUuid)] = dojo

    self._curActivityId = checkNumber(dojo.activityId)  
    self._curactivityUuid = checkNumber(dojo.activityUuid)  
    
    self:InitBambooHpParams()

    self:StartTimeDown()
end

function BambooQuestComponent:InitBambooHpParams()
    ---@type BambooUtils
    local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
    ---@type ConstantsBamboo
    local ConstantsBamboo = import('Game.UI.FightReady.UIBamboo.ConstantsBamboo')
    self.hpParams.restoreHpInterval = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.RESTORE_HP_INTERVAL))
    self.hpParams.restoreNum = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.RESTORE_NUM))
    self.hpParams.hpUpLimit = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.HP_UP_LIMIT))
    self.hpParams.buyConsumeItem = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.BUY_CONSUME_ITEM))
    self.hpParams.buyConsumeItemNum = parse_strings(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.BUY_CONSUME_ITEM_NUM))
    self.hpParams.buyNum = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.BUY_NUM))
    self.hpParams.buyDailyTimeLimit = checkNumber(BambooUtils.GetConfigParamsById(ConstantsBamboo.ParamsDefine.BUY_DAILY_TIME_LIMIT))
end

