--竹林副本首页
function BambooQuestComponent:ActivityQuestHomeReq(activityUuid, cb)
    GameUtils.Request(Interfaces.ActivityQuestHome, {activityUuid = activityUuid}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        self._curActivityId = checkNumber(jsonData.activityId)  

        self.hpData = jsonData.hpData
        self.hpData.dailyBuyHpTimes = checkNumber(jsonData.dailyBuyHpTimes)
        ---@type BambooMgr
        local BambooMgr = import("Game.UI.FightReady.UIBamboo.BambooMgr")
        BambooMgr:GetInstance():StartTimer()
        local curCount = checkNumber(GoodsUtils.GetThingNo(Constants.Currency.BambooHp))
        local deltaCount = jsonData.hpData.hp - curCount
        GoodsUtils.DrawRewards({
            {
                goodsId = Constants.Currency.BambooHp,
                num = checkInt(deltaCount)
            }
        })
        
        
        self._finishMapIds = {}
        for k, v in pairs(jsonData.chapterOverInfo) do
            self._finishMapIds[checkString(v)] = 1
        end
        
        self._curMapId = checkNumber(jsonData.chapterId)
        self._specialEventIds = {}
        for k, v in pairs(jsonData.copyUnlockEvent) do
            self._specialEventIds[checkString(v)] = 1
        end
        self._allReward = {}
        for k, v in pairs(jsonData.rewardsInfo) do
            self._allReward[checkString(k)] = checkNumber(v)
        end

        for k, v in pairs(jsonData.challengeInfo) do
            self._challengeQuestInfo[checkString(k)] = checkNumber(v)
        end

        self._starInfo = {}
        local t = checkTable(jsonData.starInfo)
        for k, v in pairs(t) do
            local _, conditions = QuestConfMgr:GetInstance():GetQuestConditions(checkString(k))
            if conditions then
                local _t = {}
                local count = 0
                v = table.values(v)
                for m, cdt in pairs(conditions) do
                    count = count + 1
                    _t[checkString(cdt.id)] = (table.keyof(v, count) and 1 or 0) 
                end
                self._starInfo[checkString(k)] = _t
            end
        end

        self._challengeCurrencySum = checkNumber(jsonData.ptCurrencySum)
        print(table.dump(self._allActivity))

        if cb then
            cb()
        end
    end)
end

function BambooQuestComponent:IsCompleteCondition(levelId, conditionId)
    local levelStarInfo = self._starInfo[checkString(levelId)]
    if levelStarInfo then
        if checkNumber(levelStarInfo[conditionId]) == 1 then
            return true
        end
    end
    return false
end

---UpdateChallengeQuestInfo 更新挑战关卡信息
---@param questId number 关卡id
function BambooQuestComponent:UpdateChallengeQuestInfo(questId, starInfo, rewardData)
    if checkNumber(questId) == 0 then
        return
    end
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if not vo then
        return
    end
    local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')

    if checkNumber(self._challengeQuestInfo[checkString(vo.type)]) < checkNumber(questId) then
        self._challengeQuestInfo[checkString(vo.type)] = checkNumber(questId)
    end

    if not QuestConfMgr:GetInstance():IsCompleteAllCondition(questId) then
        --直接覆盖
        self._starInfo[checkString(questId)] = checkTable(starInfo)
    end

    --更新积分
    if rewardData then
        for k, v in pairs(rewardData) do
            if checkNumber(v.goodsId) == BambooUtils.GetCurIntegralId(self._curactivityUuid) then
                self._challengeCurrencySum = self._challengeCurrencySum + checkNumber(v.num)
            end
        end
    end
end

---UpdateMapInfo 更新地图信息
---@param mapId number 地图id
function BambooQuestComponent:UpdateMapInfo(activityUuid, mapId)
    local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
    local _fT = BambooUtils.GetAllUnlockMapId(activityUuid)
    if checkNumber(mapId) <= 0 then
        return
    end
    self:SetFinishMapId(mapId)
    self._finishMapIds[checkString(mapId)] = 1
    local _tT = BambooUtils.GetAllUnlockMapId(activityUuid)

    if table.count(_tT) > 0 then
        local t = {}
        for i = 1, table.count(_tT) do
            if checkNumber(table.keyof(_fT, _tT[i])) == 0 then
                table.insert(t, _tT[i])
            end
        end
        self:SetNewUnlockMapId(t)
    end 
end

