---InitCurMapData 初始化当前地图信息
---@param chapterInfo table 
function BambooQuestComponent:InitCurMapData(jsonData)
    if not jsonData then
        return
    end
    local chapterInfo = jsonData.chapterInfo
    if not chapterInfo then
        return
    end

    self._curMapId = checkNumber(chapterInfo.chapter)
    self._curPlayerPosId = checkString(chapterInfo.position)
    local t = CfUtils.Split(chapterInfo.event, ",")
    if t then
        for k, v in pairs(t) do
            self:CompleteEventReq(v, true)
        end
    end

    self._allBuffId = {}
    t = CfUtils.Split(chapterInfo.buffIds, ",")
    if t then
        for k, v in pairs(t) do
            table.insert(self._allBuffId, checkNumber(v))

            --[[
            if self._allBuffId[checkString(v)] then
                self._allBuffId[checkString(v)].num = self._allBuffId[checkString(v)].num + 1
            else
                self._allBuffId[checkString(v)] = {
                    id = checkString(v),
                    num = 1
                }
            end
            ]]
        end
    end

    t = jsonData.rolesInfo
    if t then
        for k, v in pairs(t) do
            local dojo = MazeRoleDojo.New()
            dojo:Fill(v)
            self._allRoleInfo[checkString(v.id)] = dojo
        end
    end
end

