---ActivityQuestMoveReq 移动
---@param moveMap string 移动格子id
---@param eventId number 事件id
function BambooQuestComponent:ActivityQuestMoveReq(moveMap, eventId, activityUuid, cb, errCb)
    if not moveMap then
        return
    end 
    local mapStr = ""
    for i = 1, #moveMap do
        mapStr = mapStr..moveMap[i]
        if i ~= #moveMap then
            mapStr = mapStr..","
        end
    end
    GameUtils.Request(Interfaces.ActivityQuestMove, {activityUuid = activityUuid, eventId = eventId, moveMap = mapStr}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            if errCb then
                errCb()
            end
            return
        end
        local jsonData = response.data
        local chapterInfo = jsonData.chapterInfo
        --章节的buff信息
        if chapterInfo then
            self._curPlayerPosId = checkString(moveMap[table.count(moveMap)])
            if chapterInfo.buffIds then
                local t = CfUtils.Split(chapterInfo.buffIds, ",")

                local lastBuffIds = checkTable(self._allBuffId)
                self._allBuffId = {}
                if t then
                    for k, v in pairs(t) do
                        if checkNumber(table.indexof(lastBuffIds, checkNumber(v))) == 0 then
                            self._newBuffId = checkNumber(v)
                        end
                        table.insert(self._allBuffId, checkNumber(v))

                        --[[
                        if self._allBuffId[checkString(v)] then
                            self._allBuffId[checkString(v)].num = self._allBuffId[checkString(v)].num + 1
                        else
                            self._allBuffId[checkString(v)] = {
                                id = checkString(v),
                                num = 1
                            }
                        end
                        ]]
                    end
                end
                Events.Broadcast(Constants.EventNames.BambooBuffChange, nil)
            end
        end

        --血量信息
        local rolesInfo = jsonData.rolesInfo
        if rolesInfo then
            for k, v in pairs(rolesInfo) do
                local dojo = MazeRoleDojo.New()
                dojo:Fill(v)
                self._allRoleInfo[checkString(v.id)] = dojo
            end
        end

        local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
        local rewards = jsonData.rewards
        if table.count(rewards) > 0 then
            self:SetPassReward(rewards)
            GoodsUtils.DrawRewards(rewards)
            --更新积分
            for k, v in pairs(rewards) do
                if checkNumber(v.goodsId) == BambooUtils.GetCurIntegralId(self._curactivityUuid) then
                    self._challengeCurrencySum = self._challengeCurrencySum + checkNumber(v.num)
                end
            end
        end
        
        self._lastEventId = eventId
        self:CompleteEventReq(eventId)

        local ConstantsBamboo = import('Game.UI.FightReady.UIBamboo.ConstantsBamboo')
        local eventVo = BambooUtils.GetBambooEventVo(eventId)
        if eventVo then
            --结束的事件
            if checkNumber(eventVo.type) == ConstantsBamboo.GrideEventType.Finish then
                self:UpdateMapInfo(activityUuid, eventVo.chapter)
            end
        end

        if cb then
            cb()
        end
    end, function()
        if errCb then
            errCb()
        end
    end)
end

