---活动点累计奖励领取
---@param rewardId string 奖励id
function BambooQuestComponent:ActivityQuestPtRewardReq(rewardId, activityUuId, cb, activityId)
    GameUtils.Request(Interfaces.ActivityQuestPtReward, {rewardId = rewardId, activityUuid = activityUuId}, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsondata = response.data
        local rewardData = jsondata.rewards
        GoodsUtils.DrawRewards(rewardData)
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewardData } })

        --一键领取
        if checkNumber(rewardId) == 0 then
            local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')
            local t = BambooUtils.GetAllReward(activityId)
            if t then
                for k, v in pairs(t) do 
                    if BambooUtils.IsCanDrawReward(k) then
                        self._allReward[checkString(k)] = Constants.GetStatus.Has
                    end
                end
            end
        else
            self._allReward[checkString(rewardId)] = Constants.GetStatus.Has
        end 
        if cb then 
            cb()
        end
    end)
end

---CompleteEventReq 完成一个事件
---@param eventId number 事件id
---@param isInit boolean 是否是初始化  地图内完成事件增量计算
function BambooQuestComponent:CompleteEventReq(eventId, isInit)
    if checkNumber(eventId) <= 0 then
        return
    end
    self._allPassEventId[checkString(eventId)] = 1

    self:CheckWave(eventId, isInit)
end

---CheckWave 处理波次
---@param eventId number 事件id
function BambooQuestComponent:CheckWave(eventId, isInit)
    local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')

    local lastWave = self._curWave
    local eventVo = BambooUtils.GetBambooEventVo(eventId)
    if eventVo then
        self._curWave = self._curWave + checkNumber(eventVo.addWave)    
        --需要记录的事件节点
        if checkNumber(eventVo.clearTag) == 1 then
            self:CompleteSpecialEvent(eventId)
        end
    end

    if not isInit then
        Events.Broadcast(Constants.EventNames.EventBambooWaveChange, {eventId = eventId, lastWave = lastWave, curWave = self._curWave})
    end
end

---CompleteSpecialEvent 完成了特殊事件
---@param eventId integer @ 事件id
---@return integer
function BambooQuestComponent:CompleteSpecialEvent(eventId)
    if checkNumber(eventId) <= 0 then
        return
    end
    self._specialEventIds[checkString(eventId)] = 1
end

