---GetActivityOpenDay 获取活动开启天数
---@param activityUuid integer @ uuid
---@return number
function BambooQuestComponent:GetActivityOpenDay(activityUuid)
    local dojo = self:GetBambooActivityDojo(activityUuid)
    if not dojo then
        return -1
    end
    local time = checkNumber(dojo.startTime)
    if time > 0 then
        return -1
    end
    return math.abs(time) / 86400 + 1
end 

---IsActivityStart 活动是否开启
---@param activityUuid integer @ uuid
---@return boolean
function BambooQuestComponent:IsActivityStart(activityUuid)
    local dojo = self:GetBambooActivityDojo(activityUuid)
    if not dojo then
        return false
    end

    return checkNumber(dojo.startTime) <= 0 
end

---IsAcrivityEnd 活动是结束
---@param activityUuid integer @ uuid
---@return boolean
function BambooQuestComponent:IsAcrivityEnd(activityUuid)
    local dojo = self:GetBambooActivityDojo(activityUuid)
    if not dojo then
        return false
    end

    return checkNumber(dojo.endTime) <= 0 
end

---IsAcrivityClose 活动是关闭
---@param activityUuid integer @ uuid
---@return boolean
function BambooQuestComponent:IsAcrivityClose(activityUuid)
    local dojo = self:GetBambooActivityDojo(activityUuid)
    if not dojo then
        return false
    end

    return checkNumber(dojo.closeTime) <= 0 
end

