---IsPassEvent 是否通关了一个事件
---@param eventId integer @ 事件id
---@return boolean
function BambooQuestComponent:IsPassEvent(eventId)
    if not self._allPassEventId or checkNumber(eventId) == 0 then
        return false
    end
    return checkNumber(self._allPassEventId[checkString(eventId)]) == 1
end

---IsDrawReward 是否领取了奖励id
---@param rewardId integer @ 奖励id
---@return boolean
function BambooQuestComponent:IsDrawReward(rewardId)
    if checkNumber(rewardId) <= 0 then
        return false
    end

    return checkNumber(self._allReward[checkString(rewardId)]) == Constants.GetStatus.Has
end

---IsCanDrawReward 是否可以领取奖励
---@param rewardId integer @ 奖励id
---@return boolean
function BambooQuestComponent:IsCanDrawReward(rewardId)
    local BambooUtils = import('Game.UI.FightReady.UIBamboo.BambooUtils')

    if checkNumber(rewardId) <= 0 then
        return false
    end
    local vo = BambooUtils.GetBambooIntegralRewardVo(rewardId)
    if not vo then
        return false
    end
    return checkNumber(self._challengeCurrencySum) >= checkNumber(vo.needNum)

    --return checkNumber(self._allReward[checkString(rewardId)]) == Constants.GetStatus.Can
end

