---@param questId integer @ 关卡id
---@return integer
function BambooQuestComponent:GetNewQuestId(chapterId)
    return self._challengeQuestInfo[checkString(chapterId)]
end

---IsPassMap 是否通关了地图
---@param mapId integer @ 地图id
---@return boolean
function BambooQuestComponent:IsPassMap(mapId)
    return checkNumber(self._finishMapIds[checkString(mapId)]) == 1
end

---IsCompleteSpecialEvent 是否完成了特殊事件
---@param eventId integer @ 事件id
---@return boolean
function BambooQuestComponent:IsCompleteSpecialEvent(eventId)
    if checkNumber(eventId) <= 0 then
        return false
    end
    if not self._specialEventIds then
        return false
    end
    return self._specialEventIds[checkString(eventId)] == 1
end

--开始倒计时
function BambooQuestComponent:StartTimeDown()
    if not isNull(self._timeDown) then
        CDTimerModule.GetInstance():RemoveCD(self._timeDown)
        self._timeDown = nil
    end

    self._timeDown = CDTimerModule.GetInstance():AddCD(1, function(count, id)
        for k, v in pairs(self._allActivity) do
            --if checkNumber(v.startTime) > 0 then
                v.startTime = checkNumber(v.startTime) - 1
                if v.startTime == 0 then
                    Events.Broadcast(Constants.EventNames.BambooActivityOpen, {activityId = v.activityId})
                end
            --end

            if checkNumber(v.endTime) > 0 then
                v.endTime = checkNumber(v.endTime) - 1
                if v.endTime == 0 then
                    Events.Broadcast(Constants.EventNames.BambooActivityEnd, {activityId = v.activityId})
                end
            end

            if checkNumber(v.closeTime) > 0 then
                v.closeTime = checkNumber(v.closeTime) - 1
                if v.closeTime == 0 then
                    Events.Broadcast(Constants.EventNames.BambooActivityClose, {activityId = v.activityId})
                end
            end
            --print(v.startTime.."    "..v.endTime.."    "..v.closeTime)
        end
    end, CountDownTime, false, true)
end

---GetCuractivityUuid 获取当前活动uuid  多活动的时候删除
function BambooQuestComponent:GetCuractivityUuid()
    return self._curactivityUuid
end

--设置完成地图缓冲
function BambooQuestComponent:SetFinishMapId(mapId)
    self._finishMapId = checkNumber(mapId)
end

function BambooQuestComponent:GetFinishMapId()
    local id = self._finishMapId
    self._finishMapId = 0
    return checkNumber(id)
end

--设置新解锁地图缓冲
function BambooQuestComponent:SetNewUnlockMapId(mapIds)
    self._newUnlockMapIds = mapIds
end

function BambooQuestComponent:GetNewUnlockMapId()
    local t = clone(self._newUnlockMapIds)
    self._newUnlockMapIds = nil
    return t
end

--设置奖励缓冲
function BambooQuestComponent:SetPassReward(rewards)
    if not rewards or table.count(rewards) <= 0 then
        return
    end
    self._passRewards = rewards
end

function BambooQuestComponent:GetPassReward()
    local t = clone(self._passRewards)
    self._passRewards = nil
    return t
end

--设置是否进入了关卡
function BambooQuestComponent:SetEntryQuest(isTrue)
    self._isEntryQuest = checkBool(isTrue)
end

function BambooQuestComponent:GetIsEntryQuest()
    local b = checkBool(self._isEntryQuest)
    self._isEntryQuest = false
    return b
end

return BambooQuestComponent